import { signal } from '@pyreon/reactivity'
import { PyreonUI } from '@pyreon/ui-core'
import { enrichTheme } from '@pyreon/unistyle'
import rocketstyle from '@pyreon/rocketstyle'
import { Element } from '@pyreon/elements'

const theme = enrichTheme({ rootSize: 16 })

const Card = rocketstyle()({ name: 'Card', component: Element })
  .attrs({ direction: 'rows', gap: 8 })
  .theme((t, mode) => ({
    padding: 24,
    borderRadius: 12,
    backgroundColor: mode('#ffffff', '#16161d'),
    color: mode('#0a0a0e', '#f4efe6'),
  }))

export function App() {
  const scheme = signal<'light' | 'dark'>('light')
  return (
    <PyreonUI theme={theme} mode={() => scheme()}>
      <button onClick={() => scheme.update((m) => (m === 'light' ? 'dark' : 'light'))}>
        Toggle theme
      </button>
      <Card>One definition, both modes.</Card>
    </PyreonUI>
  )
}
